def copy_enquiry_ids(apps, schema_editor):
    """Older records pointed at one website enquiry; keep that link in the new list field."""
    Referral = apps.get_model("consultants", "Referral")
    for r in Referral.objects.all():
        if r.enquiry_id and not r.enquiry_ids:
            r.enquiry_ids = f",{r.enquiry_id},"
            r.save(update_fields=["enquiry_ids"])


